13	    {
14	        var lokaleZeit = datum.ToDateTime(TimeOnly.MinValue);
15	        var offset = Instanz.GetUtcOffset(lokaleZeit);
16	        if (lokaleZeit.Ticks - offset.Ticks < DateTime.MinValue.Ticks)
17	        {
18	            return DateTimeOffset.MinValue;
19	        }
20	        return new DateTimeOffset(lokaleZeit, offset);
21	    }
22	
23	    public static DateTimeOffset Tagesende(DateOnly datum)
24	    {
25	        var lokaleZeit = datum.ToDateTime(TimeOnly.MaxValue);
26	        var offset = Instanz.GetUtcOffset(lokaleZeit);
27	        if (lokaleZeit.Ticks - offset.Ticks > DateTime.MaxValue.Ticks)
28	        {
29	            return DateTimeOffset.MaxValue;
30	        }
31	        return new DateTimeOffset(lokaleZeit, offset);
