1	/**
2	 * Extrahiert den UTC-Offset (z. B. "+02:00") aus einem ISO-8601-Zeitstempel, damit Angulars
3	 * DatePipe die Spielstätten-lokale Zeit rendert statt der Zeitzone des Besucher-Browsers.
4	 * Angulars DatePipe-timezone-Parameter versteht nur feste Offsets, keine IANA-Zonennamen
5	 * (z. B. "Europe/Berlin") — der Offset kommt vom Backend bereits korrekt (DST-bewusst) berechnet.
6	 */
7	export function spielstaettenOffset(zeitpunktIso: string): string {
8	  const treffer = /(Z|[+-]\d{2}:\d{2})$/.exec(zeitpunktIso);
9	  if (!treffer) {
10	    return '+00:00';
11	  }
12	  return treffer[1] === 'Z' ? '+00:00' : treffer[1];
13	}
